import { AsyncLocalStorage } from 'node:async_hooks';

export interface RequestContext { requestId: string; tenantId: string }

export const store = new AsyncLocalStorage<RequestContext>();

export function withContext<T>(ctx: RequestContext, fn: () => T): T {
  return store.run(ctx, fn);                 // typed, scoped to the async chain
}

export function current(): RequestContext | undefined { return store.getStore(); }
